import sys; sys.path.insert(0, '/home/user/artificial-reef-survey/08_paper/data/src')
from common import *
SL = 'burkitts-reef-bargara'
SH = '07_scale/shapes/burkitts-reef-bargara/'
AL = dict(GLOBAL_ALIASES, ABC2024=r'ABC News \(journalists Sarah Howells', ICM=r'Jackson, A\. / Coastal Management \(ICM\)', RWR=r'Raised Water Research \(n\.d\.\)\. "Burkitts', SwellnetForum=r'Swellnet.*truebluebasher', ABCRadio=r'ABC Radio, "The Bright Side"', Inertia=r'The Inertia')
def build():
    r = Reef(SL, AL)
    r.F('name', "Burkitts Reef (\"Greg's Reef\"), Bargara, Queensland", 'text', 'S', 'ABC2024', 'ABC News 2024-01-28')
    r.F('country', 'Australia', 'text', 'S', 'ABC2024', 'ABC News 2024-01-28')
    r.F('lat', -24.816017, 'deg N (WGS84)', 'D', 'repo:' + SH + 'shape.json geo (centre of the traced rock PLATFORM, not the reshaped boulder zone); page status approximate', 'centre of the platform trace on Esri 2025-09-05; the reef zone is not located within +-25 m; the card gives -24.8157, 152.4675', note='Position approximate (platform, not the 1997 works).')
    r.F('lon', 152.467272, 'deg E (WGS84)', 'D', 'repo:' + SH + 'shape.json geo', 'as lat')
    r.F('year_built', 1997, 'year (Feb 1997, 2 days of excavator work)', 'S', 'RWR', 'card year field (R1, R4, R6, R8); first council application 1982')
    r.F('year_completed', 1997, 'year', 'S', 'RWR', 'card year field')
    r.F('purpose', 'surf', 'category', 'S', 'ICM', 'card purpose: remove/relocate hazardous boulders and old rail debris so the point break is surfable')
    r.F('material', 'natural basalt boulders and rock platform (reshaped; at least 12 large boulders relocated or broken down); not a built structure', 'text', 'S', 'RWR', 'card size field (R4, R8)')
    r.F('volume_m3', 300, 'm3 (rock moved)', 'S', 'RWR', 'card size field (R4, R8): ~300 m3 of rock moved')
    r.U('footprint_area_m2', 'm2', 'the reshaped zone is not located; the platform (31,485 m2, minimum, 321 x 377 m) is the stage, not the reef (shape.json). Redgard Phase 3 work zones (J&C 2007 Fig 1) were georeferenced at LOW confidence (+-25 m).')
    r.F('plan_length_alongshore_m', None, 'm', 'U', None, '', note='unknown; platform trace bbox 321 E-W x 377 N-S m is not the reef.')
    r.U('plan_length_crossshore_m', 'm', 'unknown.')
    r.U('reef_height_m', 'm', 'unknown; boulder modification, no section.')
    r.U('crest_depth_msl_m', 'm below MSL', 'no crest, seabed or datum numbers exist; the point break is a rock platform worked at low tide (tide swing ~2.5 m).')
    r.U('crest_depth_lat_m', 'm below LAT', 'as above.')
    r.U('seabed_depth_toe_m', 'm below MSL', 'unknown. Context only: shore-dive depth "to ~9 m" (card R10, datum not stated) is not a reef toe.')
    r.U('seabed_depth_at_crest_m', 'm below MSL', 'unknown.')
    r.U('depth_gap_m', 'm', 'unknown.')
    r.U('seaward_ramp_length_m', 'm', 'unknown.')
    r.U('mean_seaward_slope', 'm/m', 'unknown.')
    r.U('distance_offshore_crest_m', 'm', 'unknown; a headland point break (rock platform at the shoreline).')
    r.F('tide_spring_range_m', 2.33, 'm (spring range MHWS - MLWS, Burnett Heads)', 'D', 'repo:Maritime Safety Queensland (2026). Semidiurnal Tidal Planes 2026, Burnett Heads row (MHWS 2.94, MHWN 2.35, MLWN 1.20, MLWS 0.61 m above LAT); as held in 08_paper/data/profiles/_no_3d_model.json. https://www.msq.qld.gov.au/_/media/tmronline/msqinternet/msqfiles/home/tides/tidal-planes/2026-semidiurnal-tidal-planes.pdf (row not independently verified; see 08_paper/notes/tides_check.md)', 'MSQ 2026 Burnett Heads: MHWS 2.94 - MLWS 0.61 m above LAT = 2.33 m', note='Meso-tidal. Replaces the unsupported "tide swing ~2.5 m" of the Raised Water Research card.')
    r.F('tide_mean_range_m', 1.74, 'm (mean of spring and neap range, Burnett Heads)', 'D', 'repo:Maritime Safety Queensland (2026). Semidiurnal Tidal Planes 2026, Burnett Heads row (MHWS 2.94, MHWN 2.35, MLWN 1.20, MLWS 0.61 m above LAT); as held in 08_paper/data/profiles/_no_3d_model.json. https://www.msq.qld.gov.au/_/media/tmronline/msqinternet/msqfiles/home/tides/tidal-planes/2026-semidiurnal-tidal-planes.pdf (row not independently verified; see 08_paper/notes/tides_check.md)', '(spring 2.33 + neap 1.15)/2 = 1.74 m; MHWN 2.35, MLWN 1.20', note='Replaces 2.5 m ("tide swing", basis unknown).',
        alts=[(2.5, '"tide swing", Raised Water Research card R4, basis unknown (superseded)', 'S', 'RWR', 'card size field (R4)')])
    r.F('swell_hs_m', '0.5-2 (wave face 2-6 ft)', 'm (face height)', 'S', 'RWR', 'card outcome field (R4): face 2-6 ft; period 7-10 s; best swell window Nov-Apr', note='Face height, not Hs.')
    r.F('swell_tp_s', '7-10', 's', 'S', 'RWR', 'card outcome field (R4)')
    r.U('swell_dir', 'text', 'not stated.')
    r.F('design_wave', 'no design: boulder removal to make the existing point break surfable', 'text', 'S', 'ICM', 'card purpose field')
    r.U('arm_angle_to_shoreline_deg', 'deg', 'not applicable / unknown (edge trends of the platform: 160 and 107 deg true are not reef angles).')
    r.U('arm_angle_to_swell_deg', 'deg', 'unknown.')
    r.F('surf_outcome', 'works', 'category', 'S', 'RWR+ABC2024', 'card outcome field (R4, R8, R1); verdict "worked" was assigned by the dossier agent, evidence anecdotal (no monitoring)',
        note='Surfable days rose from "a handful" per year to ~30 days a year, with overhead (4+ ft) conditions ~4 days/yr (Andrew Pitt via RWR/Swellnet); consistent peeling face that occasionally barrels.')
    r.F('surfable_days_per_year', 30, 'days/yr (after works; "a handful" before)', 'S', 'RWR', 'card outcome field (A. Pitt, SurfingRamps.com.au, via RWR and a Swellnet comment)', note='Estimate by a researcher relayed by media, not a measurement.')
    r.F('durability', 'no reported maintenance, storm damage or re-work in nearly three decades (status Jan 2024); still surfed', 'text', 'S', 'ABC2024', 'ABC News 2024-01-28; ABC Radio 2024')
    r.U('sediment_shoreline_outcome', 'text', 'none designed; not reported.')
    r.F('cost_local', 10000, 'AUD', 'S', 'ABC2024', 'card cost field (R1, R4, R8): ~AUD 10,000 (excavator rental)', price_year=1997, currency='AUD', note='WARNING: World Bank AUD series starts 1995; 1997 rate used. Owner reportedly mortgaged his house (Ground News R7); labour was voluntary.')
    r.F('shape_on_page', 'hidden', 'category', 'S', None, '04_build/data/reefs.json footprint.display = False (read only); shape.json holds only the platform trace (LOW)')
    r.F('model_3d', 'no', 'text', 'S', None, SH + 'FEASIBILITY.md: missing crest, seabed, datum, reshaped-zone location')
    return r
